local OverseaManageMenuSettingTabCell = Class('OverseaManageMenuSettingTabCell')
local KTool = CS.Engine.Lib.KTool

--- from: Assets/BundleResources/Prefabs/OverseaManage/OverseaManageMenuSettingDialog.prefab
---@class OverseaManageMenuSettingTabCell
---@field Env                           	OverseaManageMenuSettingTabCell
---@field controller                    	Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
---@field BtnNode                       	UnityEngine.RectTransform
---@field AnimRoot                      	UnityEngine.Animation
---@field SelectTextStatus              	Game.Native.Common.UISwitchText
---@field SelectNumber                  	TMPro.TextMeshProUGUI
---@field NotTextStatus                 	Game.Native.Common.UISwitchText
---@field NotSelectNumber               	TMPro.TextMeshProUGUI
---@field RedPoint                      	UnityEngine.RectTransform
---@field Select                        	UnityEngine.RectTransform
---@field ImgLock                       	UnityEngine.RectTransform
---@field NotSelect                     	UnityEngine.RectTransform



--页签选中播Select，取消选中播Cancel，选中默认状态播SelectDefault，未选中默认状态播CancelDefault；
function OverseaManageMenuSettingTabCell:__init()
    
end

function OverseaManageMenuSettingTabCell:__delete()
    
end

function OverseaManageMenuSettingTabCell:SetCallBack(cb)
    self.callBack = cb
end

function OverseaManageMenuSettingTabCell:Awake()
    SetButtonAction(self.BtnNode.gameObject,Bind(self,self.OnSelect))
    self.AnimRoot:Play("OverseaManageMenuSettingDialogTab_CancelDefault")
end

function OverseaManageMenuSettingTabCell:RefreshUI(i,preSelIndex,data)
    self.index = i
    self.data = data
    KTool.SetActive(self.ImgLock.gameObject,data.isLock)
    --self.SelectNumber.Status = i == preSelIndex and 1 or 2
    self.NotSelectNumber.text = "0"..self.index
    CfUtils.FillText(self.SelectNumber.gameObject,"0"..self.index)
    if i == preSelIndex then
        self:OnSelect()
    end

    self:RefreshSellState()
end

function OverseaManageMenuSettingTabCell:RefreshSellState()
    if self.data.isLock then
        self.NotTextStatus.Status = 3
        self.SelectTextStatus.Status = 3
        self.ImgBg.Status = 2
        KTool.SetActive(self.RedPoint,false)
    else
        self.ImgBg.Status = 1
        ---@type MaidCoffeeComponent
        local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
        local isSell =  component:GetCurMenuIsSell(self.index)
        self.NotTextStatus.Status = isSell and 2 or 1
        self.SelectTextStatus.Status = isSell and 2 or 1
        KTool.SetActive(self.RedPoint,not isSell)
    end
end

function OverseaManageMenuSettingTabCell:OnSelect()
    self.AnimRoot:Play("OverseaManageMenuSettingDialogTab_Select")
    if not isNull(self.callBack) then
        self.callBack(self.index)
    end
end

function OverseaManageMenuSettingTabCell:DoSelect()
    self.AnimRoot:Play("OverseaManageMenuSettingDialogTab_Cancel")
end

function OverseaManageMenuSettingTabCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaManageMenuSettingTabCell